files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --pixel: 4px;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #0f0f1a 25%, transparent 25%),
                    linear-gradient(-45deg, #0f0f1a 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #0f0f1a 75%),
                    linear-gradient(-45deg, transparent 75%, #0f0f1a 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: var(--pixel) solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 #0f0f1a;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
}

h1 {
  margin: 0 0 16px;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #0f0f1a;
}

.question {
  font-size: 2rem;
  font-weight: 700;
  margin: 16px 0 24px;
  min-height: 2.5rem;
  color: var(--text);
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  padding: 12px 24px;
  border: var(--pixel) solid var(--text);
  border-radius: 0;
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 #0f0f1a;
  min-width: 80px;
}

.btn:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #0f0f1a;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  background: var(--muted);
  border-color: var(--muted);
  color: var(--bg);
}

.answer {
  flex: 1 1 100px;
}

.score-line {
  font-size: 1.25rem;
  margin: 0 0 24px;
  color: var(--muted);
}

.score-line span {
  color: var(--accent);
  font-weight: 700;
}

.actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.primary:hover {
  background: #ff5a7a;
  border-color: #ff5a7a;
}

.secondary {
  background: transparent;
  border-color: var(--muted);
  color: var(--muted);
}

.secondary:hover {
  background: var(--muted);
  color: var(--bg);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .question {
    font-size: 1.5rem;
  }
  .btn {
    font-size: 1rem;
    padding: 10px 16px;
  }
}

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let answered = false;

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function render() {
  if (current >= questions.length) {
    questionEl.textContent = 'Finished';
    answerA.hidden = true;
    answerB.hidden = true;
    nextBtn.disabled = true;
    return;
  }
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.hidden = false;
  answerB.hidden = false;
  answerA.disabled = false;
  answerB.disabled = false;
  nextBtn.disabled = false;
  answered = false;
}

function handleAnswer(choice) {
  if (answered || current >= questions.length) return;
  answered = true;
  const q = questions[current];
  if (choice === q.correct) {
    score += 1;
    scoreEl.textContent = score;
  }
  answerA.disabled = true;
  answerB.disabled = true;
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (current < questions.length) {
    current += 1;
    render();
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  scoreEl.textContent = '0';
  render();
});

render();
